-- Self-service consent proof, scoped marketing, revocation and replay safety. Synthetic data rolls back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('e1000000-0000-0000-0000-000000000001','automation-owner@test.invalid'),('e1000000-0000-0000-0000-000000000002','automation-other@test.invalid');
insert into public.tenants(id,name,slug)values('e2000000-0000-0000-0000-000000000001','Automation A','automation-a'),('e2000000-0000-0000-0000-000000000002','Automation B','automation-b');
insert into public.properties(id,tenant_id,name,property_type)values('e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Hotel A','hotel'),('e3000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','Hotel B','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','owner'),('e2000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','owner');
insert into public.guests(id,tenant_id,full_name,phone)values('e4000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Asha','+919111111111');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency,created_at)values('e5000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e4000000-0000-0000-0000-000000000001','confirmed',current_date,current_date+2,5000,'INR',now()-interval '1 day');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('e6000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','12345678001','12345678002','+919999999999','automation-test');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.consent_portal',public.create_guest_portal_link('e5000000-0000-0000-0000-000000000001'),true);
set local role anon;
select is(public.portal_command(current_setting('test.consent_portal'),null,'consent_status') ->>'updates','not_recorded','Booking alone never opts a guest in');
select throws_ok($$select public.portal_command('invalid',null,'consent_status')$$,'28000',null,'Consent requires a valid private stay link');
select throws_ok($$select public.portal_command(current_setting('test.consent_portal'),extensions.gen_random_uuid(),'consent_start','{"updates":false,"marketing":true}')$$,'22023',null,'A clear stay-update choice is required');
select set_config('test.challenge1',public.portal_command(current_setting('test.consent_portal'),'f1000000-0000-0000-0000-000000000001','consent_start','{"updates":true,"marketing":false}')::text,true);
reset role;
select is((select count(*)::integer from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),0,'Portal checkbox and challenge do not grant unverified permission');
select ok(not exists(select 1 from private.whatsapp_consent_challenges where code_hash=right(current_setting('test.challenge1')::jsonb->>'message',64)),'Only a hash of the confirmation code is stored');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-hi','919111111111','Asha','consent-hi','text','Hi','{}');
reset role;
select is((select count(*)::integer from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),0,'An inbound greeting does not grant private access or future messages');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-wrong-phone','919222222222','Other','consent-wrong-phone','text',current_setting('test.challenge1')::jsonb->>'message','{}');
reset role;
select is((select count(*)::integer from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),0,'Wrong WhatsApp sender cannot consume a valid code');
update public.guests set phone='+919333333333'where id='e4000000-0000-0000-0000-000000000001';
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-phone-changed','919111111111','Asha','consent-phone-changed','text',current_setting('test.challenge1')::jsonb->>'message','{}');
reset role;
select is((select count(*)::integer from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),0,'Guest number changes invalidate verification');
update public.guests set phone='+919111111111'where id='e4000000-0000-0000-0000-000000000001';
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-valid','919111111111','Asha','consent-valid','text',current_setting('test.challenge1')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'granted','Private stay access plus matching WhatsApp proof automatically grants stay updates');
select is((select source from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'guest_whatsapp','Consent source is recorded');
select ok((select source_message_id is not null and consent_version='stay_updates_v1'from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'Evidence references verified inbound message and agreed wording');
select is((select count(*)::integer from public.whatsapp_marketing_permissions where property_id='e3000000-0000-0000-0000-000000000001'),0,'Stay agreement never implicitly grants marketing');
select is((select count(*)::integer from public.messages where property_id='e3000000-0000-0000-0000-000000000001'and direction='out'),1,'One confirmation is queued in the guest-initiated reply window');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-valid','919111111111','Asha','consent-valid','text',current_setting('test.challenge1')::jsonb->>'message','{}');
select public.ingest_whatsapp_inbound('12345678001','consent-code-replay','919111111111','Asha','consent-code-replay','text',current_setting('test.challenge1')::jsonb->>'message','{}');
reset role;
select ok((select private.inbox_delivery_error(id)is null from public.messages where direction='out'and property_id='e3000000-0000-0000-0000-000000000001'order by created_at limit 1),'Verified confirmation passes outbound safety checks');
select is((select version from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),1,'Provider retries and consumed-code replays never re-grant');
select is((select count(*)::integer from public.messages where property_id='e3000000-0000-0000-0000-000000000001'and direction='out'),1,'Retries do not duplicate consent confirmations');
set local role anon;
select is((public.portal_command(current_setting('test.consent_portal'),null,'consent_status')->>'updates'),'granted','Guest can see verified agreement');
select ok((public.portal_command(current_setting('test.consent_portal'),'f1000000-0000-0000-0000-000000000001','consent_start','{"updates":true,"marketing":false}')->>'already_requested')::boolean,'Duplicate portal submission does not issue another challenge');
select set_config('test.challenge2',public.portal_command(current_setting('test.consent_portal'),'f1000000-0000-0000-0000-000000000002','consent_start','{"updates":true,"marketing":true}')::text,true);
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-tampered-purpose','919111111111','Asha','consent-tampered-purpose','text',replace(current_setting('test.challenge2')::jsonb->>'message',' AND OFFERS',''),'{}');
reset role;
select is((select count(*)::integer from public.whatsapp_marketing_permissions where property_id='e3000000-0000-0000-0000-000000000001'),0,'Editing the confirmation purpose cannot silently grant offers');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-offers-valid','919111111111','Asha','consent-offers-valid','text',current_setting('test.challenge2')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_marketing_permissions where property_id='e3000000-0000-0000-0000-000000000001'order by recorded_at desc,id desc limit 1),'granted','Separate offers choice is stored only after WhatsApp verification');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-stop-offers','919111111111','Asha','consent-stop-offers','text','STOP OFFERS','{}');
reset role;
select ok((select private.inbox_delivery_error(id)is not null from public.messages where consent_confirmation_offers and property_id='e3000000-0000-0000-0000-000000000001'limit 1),'Withdrawal invalidates a queued offers confirmation');
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'granted','STOP OFFERS leaves stay updates enabled');
select is((select status from public.whatsapp_marketing_permissions where property_id='e3000000-0000-0000-0000-000000000001'order by recorded_at desc,id desc limit 1),'revoked','STOP OFFERS revokes marketing automatically');
set local role anon;
select set_config('test.challenge3',public.portal_command(current_setting('test.consent_portal'),'f1000000-0000-0000-0000-000000000003','consent_start','{"updates":true,"marketing":true}')::text,true);
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-stop-all','919111111111','Asha','consent-stop-all','text','STOP','{}');
select public.ingest_whatsapp_inbound('12345678001','consent-after-stop-stale','919111111111','Asha','consent-after-stop-stale','text',current_setting('test.challenge3')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'revoked','STOP revokes automatic stay updates and invalidates pending codes');
select ok(private.is_opted_out('e3000000-0000-0000-0000-000000000001','919111111111'),'Global STOP is still enforced');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-start-only','919111111111','Asha','consent-start-only','text','START','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'revoked','START alone does not reinstate guest authorization or marketing');
set local role anon;
select set_config('test.challenge4',public.portal_command(current_setting('test.consent_portal'),'f1000000-0000-0000-0000-000000000004','consent_start','{"updates":true,"marketing":false}')::text,true);
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-new-after-stop','919111111111','Asha','consent-new-after-stop','text',current_setting('test.challenge4')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'granted','Fresh explicit verification can restore stay updates');
select is((select status from public.whatsapp_marketing_permissions where property_id='e3000000-0000-0000-0000-000000000001'order by recorded_at desc,id desc limit 1),'revoked','Stay-only resubscription never restores marketing');
set local role anon;
select public.portal_command(current_setting('test.consent_portal'),'f2000000-0000-0000-0000-000000000001','consent_revoke','{"purpose":"updates"}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'revoked','Guest portal withdrawal updates actual sending authorization');
set local role anon;
select set_config('test.challenge5',public.portal_command(current_setting('test.consent_portal'),'f1000000-0000-0000-0000-000000000005','consent_start','{"updates":true,"marketing":false}')::text,true);
reset role;
update private.whatsapp_consent_challenges set expires_at=now()-interval '1 second'where request_id='f1000000-0000-0000-0000-000000000005';
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-expired-code','919111111111','Asha','consent-expired-code','text',current_setting('test.challenge5')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'revoked','Expired verification cannot activate sending');
set local role anon;
select throws_ok($$select public.portal_command(current_setting('test.consent_portal'),extensions.gen_random_uuid(),'consent_start','{"updates":true,"marketing":false}')$$,'54000',null,'Verification issuance is rate limited per hotel guest');
select throws_ok($$select public.ingest_whatsapp_inbound('12345678001','forged','919111111111','Guest','forged','text','I AGREE TO STAY UPDATES','{}')$$,'42501',null,'Portal clients cannot forge a provider message');
reset role;

-- Restore only the synthetic last challenge for independent invalidation cases.
update private.whatsapp_consent_challenges set expires_at=now()+interval '10 minutes',cancelled_at=null where request_id='f1000000-0000-0000-0000-000000000005';
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('f3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000002','e3000000-0000-0000-0000-000000000002','12345678003','12345678004','+918888888888','other-test');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678003','consent-other-hotel','919111111111','Asha','consent-other-hotel','text',current_setting('test.challenge5')::jsonb->>'message','{}');
reset role;
select is((select count(*)::integer from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000002'),0,'Other hotel sender cannot consume a challenge');
update public.guest_access_tokens set revoked_at=now()where token_hash=encode(sha256(convert_to(current_setting('test.consent_portal'),'utf8')),'hex');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-revoked-portal','919111111111','Asha','consent-revoked-portal','text',current_setting('test.challenge5')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'revoked','Revoking a private stay link invalidates pending verification');
update public.guest_access_tokens set revoked_at=null where token_hash=encode(sha256(convert_to(current_setting('test.consent_portal'),'utf8')),'hex');
update public.reservations set status='cancelled'where id='e5000000-0000-0000-0000-000000000001';
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-cancelled-stay','919111111111','Asha','consent-cancelled-stay','text',current_setting('test.challenge5')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'revoked','Cancelled stay cannot verify a pending request');
update public.reservations set status='confirmed'where id='e5000000-0000-0000-0000-000000000001';
update public.conversations set human_handoff=true where property_id='e3000000-0000-0000-0000-000000000001'and wa_contact_id='919111111111';
select set_config('test.confirm_count',(select count(*)::text from public.messages where property_id='e3000000-0000-0000-0000-000000000001'and direction='out'),true);
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-during-handoff','919111111111','Asha','consent-during-handoff','text',current_setting('test.challenge5')::jsonb->>'message','{}');
reset role;
select is((select status from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'granted','Guest can record agreement while reception handles the conversation');
select is((select count(*)::integer from public.messages where property_id='e3000000-0000-0000-0000-000000000001'and direction='out'),current_setting('test.confirm_count')::integer,'Human handoff suppresses automatic consent replies');
select ok((select human_handoff from public.conversations where property_id='e3000000-0000-0000-0000-000000000001'and wa_contact_id='919111111111'),'Verification does not silently release human handoff');
update public.conversations set human_handoff=false where property_id='e3000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((public.whatsapp_consent_workspace('e3000000-0000-0000-0000-000000000001')->>'total')::integer,1,'Staff dashboard deduplicates stays by guest');
select throws_ok($$select public.whatsapp_consent_workspace('e3000000-0000-0000-0000-000000000002')$$,'42501',null,'Staff dashboard cannot read another hotel consent');
select public.authorize_whatsapp_stay_updates('e3000000-0000-0000-0000-000000000001','e5000000-0000-0000-0000-000000000001',(select version from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'granted','Staff verified the guest number and recorded their signed agreement.',true);
reset role;
select is((select source from public.whatsapp_guest_authorizations where property_id='e3000000-0000-0000-0000-000000000001'),'staff','Staff exception resolution updates the consent source accurately');

insert into public.guests(id,tenant_id,full_name,phone)values('f4000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Second guest','+919444444444');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)values('f5000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','f4000000-0000-0000-0000-000000000001','confirmed',current_date,current_date+1,1000,'INR');
set local role authenticated;
select set_config('test.second_portal',public.create_guest_portal_link('f5000000-0000-0000-0000-000000000001'),true);
set local role anon;
select set_config('test.cancel_request',public.portal_command(current_setting('test.second_portal'),extensions.gen_random_uuid(),'consent_start','{"updates":true,"marketing":false}')::text,true);
select public.portal_command(current_setting('test.second_portal'),extensions.gen_random_uuid(),'consent_cancel','{}');
select throws_ok($$select public.portal_command(current_setting('test.second_portal'),extensions.gen_random_uuid(),null,'{"updates":true,"marketing":false}')$$,'22023',null,'Null command cannot issue a verification challenge');
set local role service_role;
select public.ingest_whatsapp_inbound('12345678001','consent-cancelled-choice','919444444444','Second guest','consent-cancelled-choice','text',current_setting('test.cancel_request')::jsonb->>'message','{}');
reset role;
select is((select count(*)::integer from public.whatsapp_guest_authorizations where guest_id='f4000000-0000-0000-0000-000000000001'),0,'Cancelling pending choices invalidates their confirmation without granting');
set local role anon;
select public.portal_command(current_setting('test.consent_portal'),extensions.gen_random_uuid(),'consent_revoke','{"purpose":"both"}');
reset role;
select ok(private.is_opted_out('e3000000-0000-0000-0000-000000000001','919111111111'),'Stopping both scopes from the guest portal also records global withdrawal');
select ok((select consent_version='hotel_marketing_v1'and source='guest_whatsapp'and actor_id is null from public.whatsapp_marketing_permissions where property_id='e3000000-0000-0000-0000-000000000001'and status='granted'limit 1),'Marketing has its own wording version and guest source without a forged staff actor');
select *from finish();
rollback;
